 parser=argparse.ArgumentParser(); parser.add_argument('--pending-facsimiles',action='store_true'); args=parser.parse_args()
 classic=load(ROOT/'public/reader/likutay-moharan/part-1/torah-21.json'); require(len(classic.get('segments',[]))==27,'Classic physical/in-scope count must be 27')
