 require(study.get('sefariaSectionCounts')==COUNTS and all(study.get(k)==102 for k in ('sefariaPassages','totalPassages','productionAlignedPassages')) and study.get('restoredBilingualSupplements')==0,'Study count/restoration metadata mismatch')
 source=study.get('source',{}); expected_meta={'ref':'Likutei Moharan 21:1','prev':'Likutei Moharan 20:10','lastNext':'Likutei Moharan 22:1','versionTitle':'Likutey Moharan Volumes 1-11, trans. by Moshe Mykoff. Breslov Research Inst., 1986-2012','license':'CC-BY-NC','versionSource':'https://www.nli.org.il/he/books/NNL01','heVersionTitle':'Likutei Moharan - rabenubook.com','heLicense':'Public Domain','heVersionSource':'http://rabenubook.com/%D7%9C%D7%99%D7%A7%D7%95%D7%98%D7%99-%D7%9E%D7%95%D7%94%D7%A8%D7%B4%D7%9F-%D7%90/'}
 require(all(source.get(k)==v for k,v in expected_meta.items()),'Sefaria provenance mismatch'); require('editionClose' not in study and not any(x.get('insertedSupplement') for x in segs),'Synthetic restoration must be absent')
