 pettek=load(ROOT/'public/reader/pettek-nanach-commentary/torah-21.json'); psegments=pettek.get('segments',[])
 require(len(psegments)==27 and [int(x['index']) for x in psegments]==list(range(1,28)) and [int(x['relatedSegment']) for x in psegments]==list(range(1,28)) and pettek.get('layerAvailability')==AVAILABILITY,'Pettek count/availability mismatch')
 for item in psegments:
  actual={layer:{lang:bool(str((item.get('layers',{}).get(layer) or {}).get(lang) or '').strip()) for lang in ('he','en')} for layer in AVAILABILITY}; require(actual==AVAILABILITY,f'Pettek asymmetric language mismatch at {item.get("index")}'); expected=[i for i,primary in enumerate(PRIMARY,1) if primary==item['relatedSegment'] or item['relatedSegment'] in MERGED.get(i,[])]; require(item.get('alignedPassages')==expected and item.get('alignedPassage')==expected[0],f'Pettek crosswalk mismatch at {item.get("index")}')
 biur=load(ROOT/'public/reader/biur-halikutim/section-26.json'); bsegs=biur.get('segments',[]); require(biur.get('sourceSection')==26 and biur.get('displayNumber')==21 and len(bsegs)==210 and [x['index'] for x in bsegs]==list(range(1,211)) and biur.get('hasEnglish') is False and all(x.get('he') and not x.get('en') for x in bsegs),'Biur section 26 Hebrew-only package mismatch')
 parparos=load(BASE/'parparos-lechochma.json'); psegs=parparos.get('segments',[]); require(parparos.get('sourceSection')==22 and len(psegs)==20 and [x['index'] for x in psegs]==list(range(1,21)) and [x['sourceIndex'] for x in psegs]==list(range(2,41,2)) and parparos.get('hasEnglish') is False and all(x.get('he') and not x.get('en') for x in psegs),'Parparos normalization/language mismatch')
 prayer=load(ROOT/'public/reader/likutay-tefilos/part-1/prayer-21.json'); qsegs=prayer.get('segments',[]); ids=[f'p21{chr(97+i)}' for i in range(13)]; require(len(qsegs)==13 and [x['index'] for x in qsegs]==list(range(1,14)) and [x['sourceId'] for x in qsegs]==ids and prayer.get('totalParagraphs')==13,'Prayer p21a-p21m mismatch'); require(prayer.get('navigation',{}).get('prevUrl')=='/reader/likutay-tefilos/1/20' and prayer.get('navigation',{}).get('nextUrl')=='/reader/likutay-tefilos/1/22','Prayer navigation regression'); excluded=prayer.get('excludedMetadata',{}); require(excluded.get('dateBars')==4 and excluded.get('specialBars')==2 and all(x.get('he') and x.get('en') for x in qsegs),'Prayer blocks/bar metadata mismatch')
 nanach=load(BASE/'likutay-nanach.json'); nsegs=nanach.get('segments',[]); require(len(nsegs)==25 and [(x.get('sourceFile'),x.get('sourceIndex')) for x in nsegs]==[('volume-4/chapter-18.json',i) for i in range(28,53)] and all(x.get('he') and not x.get('en') for x in nsegs),'Nanach chapter 18 Hebrew-only range mismatch'); require(any(x.get('sourceIndex')==49 for x in nsegs),'Nanach index 49 missing')
 associations=load(ROOT/'src/data/lm-commentaries.json')['1']['21']['related_commentaries']; n_assoc=[x for x in associations if x.get('book')=='likutay-nanach']; require(len(n_assoc)==1 and n_assoc[0].get('url')=='/reader/likutay-nanach/volume-4/chapter-18.json' and n_assoc[0].get('sourceRange')=={'startIndex':28,'endIndex':52,'count':25},'Nanach discovery association mismatch')
 manifest=load(BASE/'peer-halikutim/manifest.json'); require(manifest.get('hebrewBooksId')==66038 and manifest.get('sourceSha256')==SHA and manifest.get('sourcePageRange')==[301,412] and len(manifest.get('pages',[]))==112 and [x['sourcePage'] for x in manifest['pages']]==list(range(301,413)),'Pe’er constants/range mismatch'); require(manifest.get('pdf')=='/reader/super/likutay-moharan/1/21/peer-halikutim/peer-halikutim-torah-21.pdf' and all(x.get('image')==f'/reader/super/likutay-moharan/1/21/peer-halikutim/page-{x["sourcePage"]}.webp' for x in manifest['pages']),'Pe’er public paths mismatch'); require('page 413 begins Torah 22' in manifest.get('textNotice','') and all('page-413.webp' not in x.get('image','') for x in manifest['pages']),'Pe’er exclusion mismatch')
 expected_assets={f'page-{n}.webp' for n in range(301,413)}; actual_assets={p.name for p in (BASE/'peer-halikutim').glob('page-*.webp')}; pdf_ready=(BASE/'peer-halikutim/peer-halikutim-torah-21.pdf').is_file(); require((not actual_assets and not pdf_ready) or (actual_assets==expected_assets and pdf_ready),'Pe’er asset readiness mismatch'); require(not args.pending_facsimiles or (not actual_assets and not pdf_ready and manifest.get('facsimileStatus')=='pending-separately-supervised-conversion'),'Explicit pending mode requires no facsimile artifacts and pending manifest')
