 for token in ('<span><b>9</b> study layers</span>','exactly 102 Hebrew leaves','21:6:3','corrupted 27 legacy Classic alignments','beginner English-only','source section 26 · 210 Hebrew-only records','source section 22 · 20 Hebrew-only records','chapter 18 indices 28–52','13 bilingual blocks p21a–p21m','Pe’er pages 301–412','page 413 begins Torah 22','https://www.peer-halikutim.com/'):
  require(token in astro,f'Route source-integrity token missing: {token}')
